jsonSpec.spec:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "databricks_query"
  },
  "width": "container",
  "height": "container",
  "padding": {
    "left": 12,
    "right": 12,
    "top": 6,
    "bottom": 4
  },
  "config": {
    "autosize": {
      "type": "fit",
      "contains": "padding"
    },
    "view": {
      "stroke": null
    }
  },
  "transform": [
    {
      "calculate": "isValid(datum.v) && datum.v > 0 ? format(datum.v, ',') : '—'",
      "as": "vt"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "text",
        "align": "center",
        "baseline": "top",
        "x": {
          "expr": "width / 2"
        },
        "y": {
          "expr": "height / 2 - 45"
        },
        "font": "Verdana",
        "fontSize": 18,
        "fontWeight": 800,
        "lineHeight": 22,
        "color": "#3F3F3F",
        "text": "checks on this table"
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "center",
        "baseline": "top",
        "x": {
          "expr": "width / 2"
        },
        "y": {
          "expr": "height / 2 - 8"
        },
        "fontSize": 36,
        "fontWeight": "bold",
        "color": {
          "expr": "mode=='dark'?'#E8EDF5':'#14213A'"
        }
      },
      "encoding": {
        "text": {
          "field": "vt"
        }
      }
    }
  ]
}
